llm.raw_content:
{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10","C18","C83","C147","C130","C154","C128","C114","C249","C215"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10","C18","C83","C249","C215"],
  "claims": [
    {
      "claim": "The closest measured context, cerivastatin, shares the 3,5-dihydroxyhept-6-enoic acid side chain and a fluorophenyl substituent and had absolute oral bioavailability 60% (90% CI 51-70%) in fasted healthy young men, with the lower bound well above the 20% threshold.",
      "card_ids": ["C10","C18"]
    },
    {
      "claim": "L3 card C83 shows that after an oral pitavastatin microdose, the pitavastatin lactone metabolite was measurable in plasma (rifampin GMR ~0.9 for Cmax and AUC), confirming oral absorption and systemic exposure of the pitavastatin scaffold; this is supportive but does not quantify absolute F.",
      "card_ids": ["C83"]
    },
    {
      "claim": "L4 cards C147, C130, C154, C128, and C114 support adequate solubility/dissolution and intestinal permeability for the acidic statin class (cerivastatin sodium freely soluble with rapid dissolution; atorvastatin Caco-2 AP-BL Papp 1.8e-6 cm/s; pH-dependent solubility for acidic statins).",
      "card_ids": ["C147","C130","C154","C128","C114"]
    },
    {
      "claim": "L5 card C193 shows cerivastatin undergoes intestinal CYP3A metabolism, yet the same molecule has measured F=60% (C10/C18), so intestinal metabolism in this class does not imply F<20%; L5 cards C198/C179 show fluvastatin is an OATP2B1 substrate, supporting possible intestinal uptake for the statin side-chain class, while no pitavastatin-specific efflux/metabolism record is present.",
      "card_ids": ["C193","C198","C179"]
    },
    {
      "claim": "L6 cards C249 and C215 provide pitavastatin-specific metabolic-stability evidence: pitavastatin lactone had low intrinsic clearance in human hepatic microsomes (4.6 µl/min/mg protein), and no marked difference in intrinsic clearance was detected between pitavastatin and its lactone form, supporting low hepatic first-pass metabolism for the free acid.",
      "card_ids": ["C249","C215"]
    },
    {
      "claim": "L6 records for fluvastatin (C224/C210/C212) and cerivastatin (C222/C241) show higher HLM intrinsic clearance, but these are different statin cores and do not transfer as low-F evidence to pitavastatin.",
      "card_ids": ["C224","C210","C212","C222","C241"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C249","C215"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for pitavastatin free acid is present in the supplied cards.",
    "No pitavastatin-specific hepatic uptake/biliary excretion or transporter record is present; low HLM intrinsic clearance does not by itself exclude transporter-mediated hepatic first-pass extraction.",
    "Transfer from cerivastatin F=60% does not control for differences in the quinoline/cyclopropyl core versus the cerivastatin pyridine core, transporter profile, or first-pass metabolism.",
    "The pitavastatin-specific L6 clearance record is for the lactone form; C215 bridges to the free acid but is not a direct free-acid clearance measurement.",
    "No direct pitavastatin-specific intestinal permeability or efflux measurement is present; L4/L5 rely on class analogs."
  ],
  "decision_summary": "Query is pitavastatin free acid. The closest measured context, cerivastatin, has absolute oral bioavailability 60% (90% CI 51-70%), far above the 20% threshold. L3 confirms oral absorption of the pitavastatin scaffold; L4 supports statin-class solubility and permeability; L5 adds only mechanistic gut-wall efflux/intestinal-metabolism evidence for other statins, with the closest cerivastatin card showing intestinal CYP3A metabolism yet F=60%. L6 adds pitavastatin-specific metabolic-stability evidence (low HLM intrinsic clearance for pitavastatin lactone, no marked difference vs free acid), supporting low hepatic first-pass metabolism. No transferable threshold-relevant low-F evidence appears. Prediction remains high, with strengthened confidence."
}

